INSERT INTO releases (version, released_on, title, public_notes, tech_notes) VALUES (
  '2.84.0',
  '2026-09-03',
  'Сейф: файлы под паролем, шифрование на устройстве',
  E'Новая страница «Сейф» (выдаётся персонально). Файлы шифруются прямо в браузере: на сервер уходят только зашифрованные байты, и открыть их без пароля не может никто — включая нас. Сервер не видит даже имён и типов файлов.\n\nПароль задаётся папке, файлы внутри шифруются каждый своим ключом. Класть можно что угодно: картинки, текст, аудио и видео открываются прямо на странице, PDF внутри Telegram не показывается (ограничение вебвью) и открывается кнопкой в браузере — там пароль спросят заново. Остальное скачивается.\n\nКлюч живёт в памяти минуту и стирается, когда вы уходите со вкладки; замок 🔒 запирает сразу — потом снова понадобится пароль. Файлы и папки можно расшарить: получатель увидит те же зашифрованные данные и откроет их, только если вы сами передадите ему пароль.\n\nМесто ограничено вашим типом пользователя — полоска сверху показывает, сколько занято (обычный 3 МБ на файл и 10 МБ всего, лимиты правит админ). Удаление сразу и навсегда, корзины нет; файл, удалённый владельцем, пропадает и у тех, кому он был расшарен.\n\n⚠️ Пароль восстановить нельзя: забыли — файлы не откроет никто.',
  E'Схема: пароль → PBKDF2-SHA256(310k) → KEK разворачивает ключ папки FK; у файла свой ключ содержимого CK под FK (key_env), метаданные тоже под FK (meta_env). Смена пароля = одна обёртка, перенос файла = 32 байта, перешифровки нет. Отдельной проверки пароля не нужно: GCM-тег на обёртке FK и есть проверка. У каждой папки свой salt — расшаренная подпапка самодостаточна.\n\nБлоб: HVLT + версия + размер чанка + база IV, дальше чанки по 4 МБ (IV = база ‖ счётчик). Чанки сразу, а не потом: файл целиком живёт в памяти в трёх копиях. Загрузка тремя ручками (init → chunk → finish), потому что fetch с ReadableStream в теле требует HTTP/2 и не работает в Safari.\n\nЛимиты: user_type_limits.vault_file_mb/vault_total_mb, правятся в админке; квота считается ВЛАДЕЛЬЦУ и проверяется дважды — на init по заявленному размеру и на finish по факту (между ними могли добавиться файлы).\n\nШаринг через общий deliverShare (kinds vault_folder/vault_file) — доступ, а не копия; текст уведомления прямо говорит, что пароль сервер не знает. Блобы отдаются через API с проверкой доступа, а не статикой.\n\nЗамок: неизвлекаемый CryptoKey в Map, TTL 60 с, автозамок на visibilitychange и при уходе со страницы, отзыв blob-URL и забывание расшифрованных имён.\n\nПроверено сквозняком в браузере: создание папки, загрузка перетаскиванием, превью, просмотр картинки и текста, замок и неверный пароль, подпапка с тем же паролем открывается сама, перенос файла между папками с переворотом ключа (файл читается на новом месте), удаление с возвратом квоты. Шаринг проверен вторым сервером с DEV_USER_ID=2: получатель видит папку и файл, качает блоб, чужой файл удалить не может, а после удаления владельцем файл пропадает и блоб отдаёт 404.'
);
-- +goose StatementEnd

